        public static WorkspaceProject WorkspaceProject(string id = default, string name = default, string description = default, string createdBy = default, WorkspaceProjectStatus status = default, int agentCount = default, DateTimeOffset createdOn = default, DateTimeOffset updatedOn = default)
        {
            return new WorkspaceProject(
                id,
                name,
                description,
                createdBy,
                status,
                agentCount,
                createdOn,
                updatedOn,
                default);
        }
    }
